import ast
import socket
import subprocess
import sys
import os
from typing import List, Dict, Any

def get_active_connections() -> List[Dict[str, Any]]:
    connections = []
    try:
        result = subprocess.run(['netstat', '-an'], capture_output=True, text=True, check=True)
        lines = result.stdout.splitlines()
        for line in lines[2:]:
            parts = line.split()
            if len(parts) >= 4:
                local_addr = parts[1]
                remote_addr = parts[2]
                state = parts[3]
                if state == 'ESTABLISHED':
                    connections.append({
                        'local': local_addr,
                        'remote': remote_addr,
                        'state': state
                    })
    except subprocess.CalledProcessError as e:
        print(f"Error retrieving network connections: {e.stderr}", file=sys.stderr)
    except FileNotFoundError:
        print("netstat command not found. Ensure it is installed.", file=sys.stderr)
    return connections

def analyze_file_security(filepath: str) -> List[str]:
    vulnerabilities = []
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            source = f.read()

        tree = ast.parse(source)

        for node in ast.walk(tree):
            if isinstance(node, ast.Call):
                if isinstance(node.func, ast.Name):
                    if node.func.id == 'eval':
                        vulnerabilities.append(f"Line {node.lineno}: Use of 'eval()' detected. Consider using ast.literal_eval() or json.loads().")
                    elif node.func.id == 'exec':
                        vulnerabilities.append(f"Line {node.lineno}: Use of 'exec()' detected. Avoid dynamic code execution.")
                    elif node.func.id == 'compile':
                        vulnerabilities.append(f"Line {node.lineno}: Use of 'compile()' detected. Avoid dynamic code compilation.")
                elif isinstance(node.func, ast.Attribute):
                    if node.func.attr == 'load':
                        if isinstance(node.func.value, ast.Name) and node.func.value.id == 'pickle':
                            vulnerabilities.append(f"Line {node.lineno}: Use of 'pickle.load()' detected. It can execute arbitrary code.")
                    elif node.func.attr == 'get':
                        if isinstance(node.func.value, ast.Name) and node.func.value.id == 'os':
                            if node.args:
                                vulnerabilities.append(f"Line {node.lineno}: Potential insecure usage of 'os.getenv' or similar.")
            elif isinstance(node, ast.Import):
                for alias in node.names:
                    if alias.name in ['pickle', 'marshal', 'shelve']:
                        vulnerabilities.append(f"Line {node.lineno}: Import of '{alias.name}' detected. Use with caution due to potential deserialization risks.")
            elif isinstance(node, ast.Call):
                if isinstance(node.func, ast.Attribute):
                    if node.func.attr == 'system':
                        vulnerabilities.append(f"Line {node.lineno}: Use of 'os.system()' detected. Consider using subprocess with shell=False.")
                    elif node.func.attr == 'popen':
                        vulnerabilities.append(f"Line {node.lineno}: Use of 'os.popen()' detected. Consider using subprocess with shell=False.")
    except FileNotFoundError:
        print(f"File not found: {filepath}", file=sys.stderr)
    except SyntaxError as e:
        print(f"Syntax error in {filepath}: {e.msg}", file=sys.stderr)
    except Exception as e:
        print(f"Error analyzing {filepath}: {str(e)}", file=sys.stderr)

    return vulnerabilities

def main():
    if len(sys.argv) < 2:
        print("Usage: python script.py <file_path> [file_path2 ...]", file=sys.stderr)
        sys.exit(1)

    files_to_analyze = sys.argv[1:]

    print("=== Active Network Connections ===")
    connections = get_active_connections()
    if connections:
        for conn in connections:
            print(f"Local: {conn['local']} | Remote: {conn['remote']} | State: {conn['state']}")
    else:
        print("No active connections found.")

    print("\n=== Security Analysis Results ===")
    for filepath in files_to_analyze:
        if not os.path.isfile(filepath):
            print(f"Skipping {filepath}: Not a valid file.", file=sys.stderr)
            continue

        if not filepath.endswith('.py'):
            print(f"Skipping {filepath}: Not a Python file.", file=sys.stderr)
            continue

        issues = analyze_file_security(filepath)
        if issues:
            print(f"\nFile: {filepath}")
            for issue in issues:
                print(f"  - {issue}")
        else:
            print(f"\nFile: {filepath} - No common security issues detected.")

if __name__ == "__main__":
    main()
